input.script:
services = boundary retry 2 { return list_services({}) } catch err {
    return fail("SVC_FAILED", err.code + ": " + err.message)
}

firsts = for s in services {
    r = boundary retry 2 { return search_logs({ service: s, level: "ERROR", page: 1 }) } catch err {
        return fail("LOGS_FAILED", s + ": " + err.code + ": " + err.message)
    }
    return { service: s, total: r.total_items, total_pages: r.total_pages }
}

suspect = fold acc = null for f in firsts {
    return f if acc == null else (f if f.total > acc.total else acc)
}

pages = for p in list.range(1, suspect.total_pages + 1) {
    r = boundary retry 2 { return search_logs({ service: suspect.service, level: "ERROR", page: p }) } catch err {
        return fail("LOGS_FAILED", suspect.service + ": " + err.code + ": " + err.message)
    }
    return r.items
}

errors = fold acc = [] for items in pages { return acc + items }

ts_raw = for e in errors {
    skip if e.ts == null
    return time.parse(e.ts)
}
ts = list.sort(ts_raw)
n = list.length(ts)
assert(n > 0, "no error timestamps for suspect")

# Burst onset: first point where 5 errors occur within 30 min (background is occasional)
i1 = fold acc = null for i in list.range(0, n - 4) {
    return acc if acc != null else (i if ts[i+4] - ts[i] < 1800000 else null)
}
# Fallback: 10 errors within 60 min
i2 = fold acc = null for i in list.range(0, n - 9) {
    return acc if acc != null else (i if ts[i+9] - ts[i] < 3600000 else null)
}
start_idx = i1 if i1 != null else (i2 if i2 != null else 0)
burst_start = ts[start_idx]

deploys = boundary retry 2 { return get_deploys({ service: suspect.service }) } catch err {
    return fail("DEPLOY_FAILED", err.code + ": " + err.message)
}
owner = boundary retry 2 { return get_service_owners({ service: suspect.service }) } catch err {
    return fail("OWNER_FAILED", err.code + ": " + err.message)
}

candidates = for d in deploys {
    skip if d.deployed_at == null or d.sha == null
    t = time.parse(d.deployed_at)
    skip if t > burst_start
    return { sha: d.sha, t }
}
chosen = fold acc = null for c in candidates {
    return c if acc == null else (c if c.t > acc.t else acc)
}
assert(chosen != null, "no deploy before burst start")
assert(owner.owner_email != null, "no owner email")

res = submit_result({ answer: { service: suspect.service, deploy_sha: chosen.sha, owner_email: owner.owner_email } })

return {
    recorded: res.recorded,
    service: suspect.service,
    deploy_sha: chosen.sha,
    owner_email: owner.owner_email,
    burst_start: time.format(burst_start),
    deploy_time: time.format(chosen.t),
    suspect_total_errors: suspect.total,
    totals: for f in firsts { return { service: f.service, total: f.total } }
}
